/*
 * The savefile helper's shared declarations, and the switch that picks one game's
 * address table.
 *
 * This header is compiled only by the PS3 cross compiler, into code that runs
 * inside the game's own process. Nothing in qwark itself includes it: what qwark
 * carries is the generated byte arrays in src/games/sfhelper_bins.c.
 *
 * Every game function the helper calls is declared here and left undefined. The
 * link resolves each one to a hard address with --defsym, from the SF_FN_* lines
 * in the game's header, so a call compiles to a plain relative branch and the
 * game's TOC register is never touched.
 */
#ifndef QWARK_SFHELPER_H
#define QWARK_SFHELPER_H

#define SF_RAC1 1
#define SF_RAC2 2
#define SF_RAC3 3
#define SF_RAC4 4

#ifndef SF_GAME
#error "SF_GAME must be 1, 2, 3 or 4; build.sh passes it"
#endif

#if SF_GAME == SF_RAC1
#include "sf_rac1.h"
#elif SF_GAME == SF_RAC2
#include "sf_rac2.h"
#elif SF_GAME == SF_RAC3
#include "sf_rac3.h"
#elif SF_GAME == SF_RAC4
#include "sf_rac4.h"
#else
#error "SF_GAME is not a game this helper knows"
#endif

typedef unsigned char      sf_u8;
typedef unsigned short     sf_u16;
typedef unsigned int       sf_u32;
typedef unsigned long long sf_u64;

/*
 * The three address widths the helper ever reads or writes. Everything the game
 * owns is 32 bits wide, pointers included, so nothing here is ever a C pointer
 * that the 64-bit compiler would size at eight bytes.
 */
#define SF_BYTE(addr) (*(volatile sf_u8 *)(sf_u32)(addr))
#define SF_WORD(addr) (*(volatile sf_u32 *)(sf_u32)(addr))

/* How much of the save buffer one memcpy call moves. The mods all used 32 KB. */
#define SF_CHUNK 0x8000u

/*
 * Build 43. What the helper puts in a request byte when it drops the request
 * rather than doing the work, which means one thing: the game was not
 * somewhere the request could be met - Deadlocked busy on the frame the request
 * was seen, or, for a load in the other three, the game somewhere its pause
 * cannot be entered from or never coming to it.
 *
 * The request byte is the whole interface in both directions, and it already
 * carries more than 0 and 1 - Deadlocked's load parks a 2 in api_load for as
 * long as its menu is up - so a refusal is one more value of it. The request is
 * over when this goes in: the helper does not hold it for a later frame,
 * because a load that fires at some moment the player did not ask for is worse
 * than one that plainly did not happen. qwark reads the code on its next tick,
 * puts the byte back to 0 and reports SAVEFILE_ERR_NOT_IDLE, so the client
 * shows a reason rather than a request that came to nothing.
 * SAVEFILE_HELPER_REFUSED in src/core/savefile.h is the same number.
 */
#define SF_API_REFUSED 0xFE

/*
 * Build 53, RaC1, RaC2 and RaC3. The other reason a request is dropped: there
 * is no save to act on. A set-aside found the game's save buffer missing or
 * holding something that is not a save, which is how each of the three starts
 * until it has saved or loaded once; a load found the aside buffer holding
 * something that is not a save, or nothing at all and no save in the game to
 * fill it from. Up to build 52 the first copied from wherever the pointer
 * pointed - address 0 in RaC2 and RaC3 - and the second handed the loader
 * whatever was there. qwark reports SAVEFILE_ERR_NO_SAVE.
 * SAVEFILE_HELPER_NO_SAVE in src/core/savefile.h is the same number.
 */
#define SF_API_NO_SAVE 0xFD

/*
 * Build 53, RaC1 and RaC3: how long a load waits for the game's pause before
 * it is dropped with SF_API_REFUSED, ten seconds of the timebase. The console
 * runs it at 79.8 MHz, which is what lv2 answers the games' own question for
 * it with (syscall 147, sys_time_get_timebase_frequency, RaC1 0x52CA84) and
 * what RPCS3 runs it at too; ten seconds fit the low word with room to spare.
 */
#define SF_PAUSE_WAIT_TICKS 798000000u

/* The game's own memcpy, in every game. */
void sf_memcpy(void *dst, const void *src, int len);

#if SF_GAME == SF_RAC4
/* Deadlocked calls its loader in two steps; see sfhelper.c. */
void sf_restore_saved_game(int unk, void *buf);
void sf_magic_load(void);
#else
void sf_perform_load(int unk, void *buf);
#endif

#if SF_GAME == SF_RAC1
/* RaC1's save, load and autosave menus, which the Force autosave action drives. */
void sf_save_handler(int mode);

/*
 * The start menu entered by writing the state, with the menu words its update
 * reads put back as the Start button's opener puts them (sf_rac1.h).
 */
void sf_enter_menu(void);
#endif

#if SF_GAME == SF_RAC3
/* mode_requestChange. 0 when the change was taken. */
int sf_request_mode(int mode, int push, int screen, int unk, void *flag);
#endif

#if SF_GAME == SF_RAC2
/*
 * Build 53: RaC2 enters its pause by writing the mode, as RaC1 does, and puts
 * away what a cutscene leaves behind the way the Start button's skip does
 * (sf_rac2.h): the movie player's Bink file closed, the cutscene's queue of
 * movies and scenes emptied. Both take the game's object.
 */
void sf_movie_stop(sf_u32 player);
void sf_scene_clear(sf_u32 queue);
#endif

#if SF_GAME == SF_RAC3
/*
 * Build 53: the sceNpTrophy stubs the reset calls (sf_rac3.h). Every address is a 32-bit one in a 64-bit register, as the
 * game's own calls pass them; `space` is on the caller's stack. Each stub call
 * clobbers r2, and sfhelper.c restores it.
 */
int  sf_np_trophy_create_context(sf_u32 context_out, sf_u32 comm_id, sf_u32 comm_sign,
                                 sf_u64 options);
int  sf_np_trophy_create_handle(sf_u32 handle_out);
int  sf_np_trophy_destroy_context(sf_u32 context);
int  sf_np_trophy_destroy_handle(sf_u32 handle);
int  sf_np_trophy_disk_space(sf_u32 context, sf_u32 handle, sf_u64 *space, sf_u64 options);
int  sf_np_trophy_register_context(sf_u32 context, sf_u32 handle, sf_u32 callback,
                                   sf_u32 arg, sf_u64 options);

/*
 * Build 53: the game's import stubs for thread creation and exit (sf_rac3.h).
 * Every pointer either takes is a 32-bit address in a 64-bit register, as the
 * game's own calls pass them: `id` is on the caller's stack, which is below
 * 4 GB. A call to the first clobbers r2; sfhelper.c restores it.
 */
int  sf_ppu_thread_create(sf_u64 *id, sf_u32 entry, sf_u64 arg, sf_u32 prio,
                          sf_u32 stacksize, sf_u64 flags, sf_u32 name);
void sf_ppu_thread_exit(sf_u64 value) __attribute__((noreturn));
#endif

#endif /* QWARK_SFHELPER_H */
